using EarthUnscripted.TerrainDraft;using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Security.Cryptography;using System.Text;using System.Threading;using EarthUnscripted.TerrainDraft.AuthoringJson;
namespace EarthUnscripted.TerrainDraft.Core800 {
 public sealed class CoreSourceContext {public readonly RoadTerrainSource Source;public readonly TerrainDem Dem;public readonly string SourceDigest,RawDocumentDigest,ControlDigest,GroundPacketDigest,DemInputDigest,StructureLedgerDigest;public readonly Dictionary<string,SourceRoadRow[]> Frames;internal CoreSourceContext(RoadTerrainSource source,TerrainDem dem,string src,string raw,string control,string packet,string demDigest,string structure,Dictionary<string,SourceRoadRow[]> frames){Source=source;Dem=dem;SourceDigest=src;RawDocumentDigest=raw;ControlDigest=control;GroundPacketDigest=packet;DemInputDigest=demDigest;StructureLedgerDigest=structure;Frames=frames;}}
 public static class CoreSourceReader {
  public const string PacketPath="/private/tmp/rr019-authoring-candidate/newraw-wholegraph-v1/core-ground-v7/ground-packets.json",RawPath="/private/tmp/rr019-authoring-candidate/newraw-pantside-v1/original-envelope.json";
  public static string Hash(byte[] b){using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
  static byte[] BoundedRead(string path,CancellationToken token){token.ThrowIfCancellationRequested();using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(stream.Length<1||stream.Length>64L*1024*1024)throw new InvalidDataException("Reviewed source file exceeds64MiB input budget");var bytes=new byte[(int)stream.Length];int offset=0;while(offset<bytes.Length){token.ThrowIfCancellationRequested();int n=stream.Read(bytes,offset,Math.Min(65536,bytes.Length-offset));if(n<=0)throw new EndOfStreamException("Source changed during bounded read");offset+=n;}if(stream.ReadByte()!=-1)throw new InvalidDataException("Source grew during bounded read");return bytes;}}
  public static CoreSourceContext Read(CancellationToken token=default)=>Read(PacketPath,RawPath,token);
  public static CoreSourceContext Read(string packetPath,string rawPath,CancellationToken token=default){byte[] bytes=BoundedRead(packetPath,token),rawBytes=BoundedRead(rawPath,token);string packetHash=Hash(bytes),rawHash=Hash(rawBytes);if(packetHash!="d7837532b503431a72f2afd1900c87127589ad275acfbe6b6def9b4a126dd8af"||rawHash!="fd3b6201584eac1e3303b1392c21896a2a0c76774149f389cc3ace17022803cb")throw new InvalidDataException("FrozenV7source bytepins changed; no metadataflag admits it");var doc=JsonDocument.Parse(bytes).RootElement;var envelope=JsonDocument.Parse(rawBytes).RootElement;var geo=envelope.GetProperty("geography");if(doc.GetProperty("sourceEnvelopeSHA256").GetString()!=rawHash||doc.GetProperty("source2").GetString()!="f16323b89e4818e6ee57e6847a1798e742b47195a311fb3facd3a8682c8ed62d")throw new InvalidDataException("Rawsource/context binding");var owners=doc.GetProperty("ownerTable").EnumerateArray().ToArray();var ownerIds=owners.Select(p=>p.GetProperty("id").GetString()).ToArray();var ownerHeights=owners.Select(p=>(double)p.GetProperty("height").GetSingle()).ToArray();var rawRoads=geo.GetProperty("roads").EnumerateArray().ToDictionary(p=>p.GetProperty("id").GetString());var packets=new List<RoadTerrainSourcePacket>();var frames=new Dictionary<string,SourceRoadRow[]>();int wholePackets=0,selectedPackets=0;foreach(var p in doc.GetProperty("packets").EnumerateArray()){token.ThrowIfCancellationRequested();wholePackets++;if(p.GetProperty("classification").GetString()!="Ground")throw new InvalidDataException("Explicit ground classification required");var points=p.GetProperty("vertices").EnumerateArray().Select(v=>new[]{v.GetProperty("x").GetSingle(),v.GetProperty("y").GetSingle(),v.GetProperty("z").GetSingle()}).ToArray();if(points.Min(v=>v[0])>416||points.Max(v=>v[0])< -416||points.Min(v=>v[2])>416||points.Max(v=>v[2])< -416)continue;selectedPackets++;string id=p.GetProperty("id").GetString(),road=p.GetProperty("sourceRoadId").GetString();string[] members=!string.IsNullOrEmpty(road)?new[]{road}:p.GetProperty("memberRoadIds").EnumerateArray().Select(v=>v.GetString()).ToArray();foreach(string member in members){if(!rawRoads.TryGetValue(member,out var r)||r.GetProperty("bridge").GetBoolean()||r.GetProperty("tunnel").GetBoolean())throw new InvalidDataException("Ground member binds unknown/structural rawroad");}var xyz=points.SelectMany(v=>v).ToArray();var indices=p.GetProperty("triangles").EnumerateArray().Select(v=>v.GetInt32()).ToArray();int[] ownerIndex;if(p.TryGetProperty("triangleOwnerIndex",out var oi))ownerIndex=oi.EnumerateArray().Select(v=>v.GetInt32()).ToArray();else{int cap=p.GetProperty("ownerIndex").GetInt32();ownerIndex=Enumerable.Repeat(cap,indices.Length/3).ToArray();}if(ownerIndex.Length!=indices.Length/3)throw new InvalidDataException("Pertriangle sourceownership length");var tags=new string[ownerIndex.Length];for(int i=0;i<tags.Length;i++){int o=ownerIndex[i];if(o<0)continue;if(o>=owners.Length)throw new InvalidDataException("Foreign sourceowner");tags[i]=ownerIds[o];for(int j=0;j<3;j++)if((double)xyz[indices[i*3+j]*3+1]!=ownerHeights[o])throw new InvalidDataException("Taggedsource triangle differs from exactownerfloatplane");}double[] sourceS=p.TryGetProperty("rowSourceS",out var ss)?ss.EnumerateArray().Select(v=>v.GetDouble()).ToArray():Array.Empty<double>();var packet=new RoadTerrainSourcePacket(id,members,RoadTerrainSurfaceClass.Ground,0,0,0,xyz,indices,sourceS,tags);packets.Add(packet);if(!string.IsNullOrEmpty(road)&&sourceS.Length>0)frames.Add(road,SourceRoadRows.FromOriginalPacket(packet,p.GetProperty("columns").GetInt32(),p.GetProperty("rowHorizontalH").EnumerateArray().Select(v=>v.GetDouble()).ToArray(),p.GetProperty("previousSide").EnumerateArray().Select(v=>v.GetBoolean()).ToArray()));}
   var dem=new TerrainDem(geo.GetProperty("minX").GetDouble(),geo.GetProperty("minZ").GetDouble(),geo.GetProperty("width").GetDouble(),geo.GetProperty("depth").GetDouble(),geo.GetProperty("nx").GetInt32(),geo.GetProperty("nz").GetInt32(),geo.GetProperty("heights").EnumerateArray().Select(v=>(double)v.GetSingle()).ToArray());var source=new RoadTerrainSource(packets,dem,token);Console.WriteLine("FrozenV7intake "+selectedPackets+"/"+wholePackets+" packets "+source.GroundTriangles+"triangles");return new CoreSourceContext(source,dem,doc.GetProperty("source2").GetString(),rawHash,doc.GetProperty("authoringControlSHA256").GetString(),packetHash,Hash(Encoding.UTF8.GetBytes(geo.GetRawText())),Hash(Encoding.UTF8.GetBytes("V7GroundOnly: structures explicitlyunsupported outside core; no structuregeometry claim")),frames);
  }
 }
